PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;


void PageHandlerAsyncWaiter::GetBufferedLogs(
    std::vector<LogEntryPtr>* out_logs) {
  base::RunLoop loop;
  proxy_->GetBufferedLogs(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<LogEntryPtr>* out_logs
,
             std::vector<LogEntryPtr> logs) {*out_logs = std::move(logs);
            loop->Quit();
          },
          &loop,
          out_logs));
  loop.Run();
}

std::vector<LogEntryPtr> PageHandlerAsyncWaiter::GetBufferedLogs(
    ) {
  std::vector<LogEntryPtr> async_wait_result;
  GetBufferedLogs(&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::GetDebugInfo(
    DebugInfoPtr* out_info) {
  base::RunLoop loop;
  proxy_->GetDebugInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             DebugInfoPtr* out_info
,
             DebugInfoPtr info) {*out_info = std::move(info);
            loop->Quit();
          },
          &loop,
          out_info));
  loop.Run();
}

DebugInfoPtr PageHandlerAsyncWaiter::GetDebugInfo(
    ) {
  DebugInfoPtr async_wait_result;
  GetDebugInfo(&async_wait_result);
  return async_wait_result;
}




